Object.assign(SNIP,{"l47var": "#include <variant>\nvariant<int, string> v = 5;             // đang giữ int (index 0)\nv = \"xin chao\";                         // giờ giữ string (index 1), int cũ bị bỏ\nv.index();                              // 1\nholds_alternative<string>(v);           // true\nget<string>(v);                         // \"xin chao\";  get<int>(v) ném bad_variant_access", "l47opt": "#include <optional>\noptional<int> timViTri(const vector<int>& v, int x) {\n    for (int i = 0; i < (int)v.size(); i++)\n        if (v[i] == x) return i;        // có giá trị\n    return nullopt;                     // không có giá trị (cũng có thể viết return {};)\n}\noptional<int> r = timViTri(v, 8);\nif (r) cout << *r;                      // kiểm tra rồi mới lấy: *r hoặc r.value()\ncout << r.value_or(-1);                 // trống thì dùng giá trị mặc định"});PRESET_NOTES["l47"]={"Ví dụ: optional cho kết quả tìm kiếm": "Kiểu trả về optional<int> nói rõ “có thể không có kết quả”. return i; tự gói i thành optional có giá trị; return nullopt; là trống. if (a) kiểm tra, *a lấy giá trị. ten->size() gọi hàm của string bên trong optional.", "Ví dụ: value(), value_or và ngoại lệ": "value_or(0) trả về 0 khi không chia được. value() trên optional trống ném bad_optional_access (Bài 46), bắt được bằng catch. return {}; trả về optional trống.", "Ví dụ: optional của struct": "optional giữ hẳn một bản HocVien bên trong (không phải con trỏ), nên dùng g->ten như con trỏ nhưng không lo trỏ vào vùng nhớ đã mất.", "Lỗi: value() khi optional trống": "tuoi chưa được gán nên trống; value() ném bad_optional_access và không có catch nào nên chương trình dừng. Còn *tuoi thì không ném gì: đọc ra giá trị rác (hành vi không xác định).", "Ví dụ: variant giữ một trong nhiều kiểu": "Một biến v lúc giữ int, lúc giữ string; index() cho biết đang là kiểu thứ mấy (đếm từ 0). get lấy theo tên kiểu hoặc theo chỉ số. Tạo mặc định thì giữ kiểu đầu tiên với giá trị 0.", "Ví dụ: kết quả hoặc lý do lỗi": "Hàm trả về HOẶC một số, HOẶC một chuỗi giải thích. Khác optional: khi thất bại vẫn biết lý do; khác ngoại lệ: người gọi xử lý ngay tại chỗ, không nhảy qua nhiều tầng.", "Ví dụ: visit với struct có operator()": "visit nhìn kiểu đang giữ rồi gọi đúng operator() tương ứng. Thiếu operator() cho một kiểu nào đó thì lỗi biên dịch, nên không bao giờ quên xử lý một trường hợp.", "Lỗi: get sai kiểu": "v đang giữ int nên get<string> ném bad_variant_access; không có catch nên chương trình dừng. Kiểm tra bằng holds_alternative<string>(v) trước khi get.", "Lỗi: gán kiểu không có trong variant": "2.5 là double, không phải int hay string. C++17 (g++ 10 trở lên) không cho tự thu hẹp double thành int khi chọn kiểu cho variant, nên đây là lỗi biên dịch."};EX_HINTS["l47"]=[["return x; tự gói thành optional có giá trị.", "Ở main: if (r) rồi mới dùng *r."], ["Số âm không có căn: trả về nullopt ngay.", "Lấy k = (long long)sqrt((double)n) rồi chỉnh k lên/xuống một chút cho chắc (sqrt của số thực có thể lệch), cuối cùng so k·k với n."], ["push_back(stoi(w)) đặt một int vào variant; push_back(w) đặt một string.", "holds_alternative<int>(x) cho biết phần tử đang giữ số hay chữ."]];
/* ===================== BÀI 47 · optional, variant ===================== */
/* Bài 47 · optional, variant
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const P47=[{label:"Ví dụ: optional cho kết quả tìm kiếm",input:"",code:"#include <iostream>\n#include <optional>\n#include <vector>\n#include <string>\nusing namespace std;\n\noptional<int> timViTri(const vector<int>& v, int x) {\n    for (int i = 0; i < (int)v.size(); i++) {\n        if (v[i] == x) return i;\n    }\n    return nullopt;\n}\nint main() {\n    vector<int> v = {4, 8, 15};\n    optional<int> a = timViTri(v, 8);\n    optional<int> b = timViTri(v, 7);\n    if (a) cout << \"8 o vi tri \" << *a << \"\\n\";\n    if (!b) cout << \"Khong co 7\\n\";\n    cout << b.value_or(-1) << \" \" << a.has_value() << \"\\n\";\n    optional<string> ten;\n    ten = \"An\";\n    cout << ten->size() << \" \" << ten.value() << \"\\n\";\n    ten.reset();\n    cout << (ten == nullopt) << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: value(), value_or và ngoại lệ",input:"",code:"#include <iostream>\n#include <optional>\n#include <stdexcept>\nusing namespace std;\n\noptional<double> chia(double a, double b) {\n    if (b == 0) return {};\n    return a / b;\n}\nint main() {\n    cout << chia(6, 4).value_or(0) << \"\\n\";\n    cout << chia(1, 0).value_or(0) << \"\\n\";\n    auto r = chia(1, 0);\n    try {\n        cout << r.value() << \"\\n\";\n    } catch (const bad_optional_access& e) {\n        cout << \"Loi: \" << e.what() << \"\\n\";\n    }\n    return 0;\n}"},{label:"Ví dụ: optional của struct",input:"",code:"#include <iostream>\n#include <optional>\n#include <vector>\n#include <string>\nusing namespace std;\n\nstruct HocVien {\n    string ten;\n    int diem;\n};\noptional<HocVien> timGioi(const vector<HocVien>& ds) {\n    for (const auto& h : ds) {\n        if (h.diem >= 9) return h;\n    }\n    return nullopt;\n}\nint main() {\n    vector<HocVien> lop = {{\"An\", 7}, {\"Binh\", 9}, {\"Chi\", 10}};\n    auto g = timGioi(lop);\n    if (g) cout << \"Hoc vien gioi dau tien: \" << g->ten << \" (\" << g->diem << \")\\n\";\n    vector<HocVien> lop2 = {{\"Dung\", 5}};\n    if (!timGioi(lop2)) cout << \"Lop 2 chua co hoc vien gioi\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Lỗi: value() khi optional trống",input:"",code:"#include <iostream>\n#include <optional>\nusing namespace std;\n\nint main() {\n    optional<int> tuoi;\n    cout << \"Nhap xong\\n\";\n    cout << tuoi.value() << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: variant giữ một trong nhiều kiểu",input:"",code:"#include <iostream>\n#include <variant>\n#include <string>\nusing namespace std;\n\nint main() {\n    variant<int, string> v = 5;\n    cout << v.index() << \" \" << get<int>(v) << \"\\n\";\n    v = \"xin chao\";\n    cout << v.index() << \" \" << get<string>(v) << \"\\n\";\n    if (holds_alternative<string>(v)) cout << \"Dang giu chuoi\\n\";\n    variant<int, double> d;\n    cout << d.index() << \" \" << get<0>(d) << \"\\n\";\n    d = 2.5;\n    cout << d.index() << \" \" << get<double>(d) << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: kết quả hoặc lý do lỗi",input:"",code:"#include <iostream>\n#include <variant>\n#include <string>\n#include <cmath>\nusing namespace std;\n\nvariant<double, string> canBacHai(double x) {\n    if (x < 0) return string(\"so am khong co can thuc\");\n    return sqrt(x);\n}\nint main() {\n    double ds[] = {16, -4, 2};\n    for (double x : ds) {\n        auto r = canBacHai(x);\n        if (holds_alternative<double>(r)) {\n            cout << \"can(\" << x << \") = \" << get<double>(r) << \"\\n\";\n        } else {\n            cout << \"can(\" << x << \"): \" << get<string>(r) << \"\\n\";\n        }\n    }\n    return 0;\n}"},{label:"Ví dụ: visit với struct có operator()",input:"",code:"#include <iostream>\n#include <variant>\n#include <string>\n#include <vector>\nusing namespace std;\n\nstruct InRa {\n    void operator()(int x) const { cout << \"so nguyen \" << x << \"\\n\"; }\n    void operator()(const string& s) const { cout << \"chuoi \\\"\" << s << \"\\\"\\n\"; }\n    void operator()(double d) const { cout << \"so thuc \" << d << \"\\n\"; }\n};\nint main() {\n    vector<variant<int, string, double>> ds = {1, string(\"hai\"), 3.5};\n    for (const auto& x : ds) {\n        visit(InRa{}, x);\n    }\n    return 0;\n}"},{label:"Lỗi: get sai kiểu",input:"",code:"#include <iostream>\n#include <variant>\n#include <string>\nusing namespace std;\n\nint main() {\n    variant<int, string> v = 5;\n    cout << get<string>(v) << \"\\n\";\n    return 0;\n}"},{label:"Lỗi: gán kiểu không có trong variant",input:"",code:"#include <iostream>\n#include <variant>\n#include <string>\nusing namespace std;\n\nint main() {\n    variant<int, string> v = 2.5;\n    return 0;\n}"}];
const sim47=makeSim2(document.getElementById("sim-l47"),{id:"s47",presets:P47});
makeEx2(document.getElementById("ex-l47"),sim47,[{t:"Số chia hết đầu tiên",d:"Viết hàm <code>optional&lt;int&gt; timChiaHet(const vector&lt;int&gt;&amp; v, int k)<\/code> trả về số đầu tiên trong v chia hết cho k, không có thì trả về <code>nullopt<\/code>. Nhập n, dãy, rồi q giá trị k; với mỗi k in số tìm được hoặc <code>Khong co<\/code>.",tests:[{in:"5\n7 10 9 14 3\n3\n5\n3\n4",out:"10\n9\nKhong co"},{in:"1\n1\n1\n2",out:"Khong co"}],start:"#include <iostream>\n#include <optional>\n#include <vector>\nusing namespace std;\n\n// optional<int> timChiaHet(const vector<int>& v, int k) { ... }\nint main() {\n    int n;\n    cin >> n;\n    vector<int> v(n);\n    for (int& x : v) cin >> x;\n    int q;\n    cin >> q;\n    for (int i = 0; i < q; i++) {\n        int k;\n        cin >> k;\n        // auto r = timChiaHet(v, k);\n    }\n    return 0;\n}",need:/optional\s*<\s*int\s*>\s*timChiaHet/,needMsg:"Hãy viết hàm optional<int> timChiaHet(...)."},{t:"Căn bậc hai đúng",d:"Viết <code>optional&lt;long long&gt; canDung(long long n)<\/code>: nếu n là số chính phương (n = k·k với k ≥ 0) thì trả về k, ngược lại trả về nullopt. Nhập q số; với mỗi số in k, hoặc <code>-<\/code> nếu không phải số chính phương. Dùng <code>value_or<\/code> hoặc kiểm tra <code>has_value()<\/code>.",tests:[{in:"4\n16\n15\n0\n1000000000000",out:"4\n-\n0\n1000000"},{in:"2\n-4\n1",out:"-\n1"}],start:"#include <iostream>\n#include <optional>\nusing namespace std;\n\n// optional<long long> canDung(long long n) { ... }\nint main() {\n    int q;\n    cin >> q;\n    for (int i = 0; i < q; i++) {\n        long long n;\n        cin >> n;\n    }\n    return 0;\n}",need:/optional\s*<\s*long\s+long\s*>/,needMsg:"Hãy viết hàm trả về optional<long long>."},{t:"Số hay chữ",d:"Nhập n rồi n từ. Từ nào chỉ gồm chữ số thì lưu dạng <code>int<\/code>, còn lại lưu dạng <code>string<\/code>, tất cả trong một <code>vector&lt;variant&lt;int, string&gt;&gt;<\/code>. Sau đó duyệt vector: in tổng các số trên dòng 1, các chữ nối nhau bởi một dấu cách trên dòng 2 (theo thứ tự xuất hiện), số lượng chữ trên dòng 3. (Các số không quá 9 chữ số.)",tests:[{in:"5\n12 ab 30 x9 7",out:"49\nab x9\n2"},{in:"2\nmot hai",out:"0\nmot hai\n2"},{in:"1\n5",out:"5\n\n0"}],start:"#include <iostream>\n#include <variant>\n#include <vector>\n#include <string>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<variant<int, string>> ds;\n    for (int i = 0; i < n; i++) {\n        string w;\n        cin >> w;\n        // toàn chữ số: ds.push_back(stoi(w)); không thì ds.push_back(w);\n    }\n    // duyệt ds: holds_alternative<int>(x), get<int>(x), get<string>(x)\n    return 0;\n}",need:/variant\s*<\s*int\s*,\s*string\s*>/,needMsg:"Hãy dùng vector<variant<int, string>>."}]);

makeQuiz("quiz47","score47",[{"q": "Hàm tìm kiếm có thể không thấy kết quả. Kiểu trả về nào nói rõ điều đó nhất?", "o": ["int (trả về −1 khi không thấy)", "optional<int>", "int*", "void"], "a": 1, "e": "optional<int> ghi ngay trong kiểu rằng có thể không có giá trị; người gọi phải kiểm tra."}, {"q": "<code>optional&lt;int&gt; x;<\/code> (chưa gán). <code>x.value_or(7)<\/code> là:", "o": ["0", "7", "Ném ngoại lệ", "Giá trị rác"], "a": 1, "e": "x trống nên value_or trả về giá trị mặc định 7."}, {"q": "<code>variant&lt;int, string&gt; v = \"ab\";<\/code> thì <code>v.index()<\/code> là:", "o": ["0", "1", "2", "Lỗi biên dịch"], "a": 1, "e": "\"ab\" được chọn vào kiểu string, là kiểu thứ hai (index 1)."}, {"q": "v đang giữ int. <code>get&lt;string&gt;(v)<\/code> sẽ:", "o": ["Trả về chuỗi rỗng", "Ném bad_variant_access", "Đổi int thành chuỗi", "Lỗi biên dịch"], "a": 1, "e": "get sai kiểu đang giữ thì ném ngoại lệ; kiểm tra trước bằng holds_alternative."}]);

